label("$x$", (2, -1), N+N+N+W);
label("$y$", (5.5+.3, .5-.3), S);
label("$y$", (6.5+.3, 0));
label("$y$", (5+.5, -1.5+.3));
label("$110^\circ$",(2.5,3.5));
label("$100^\circ$",(6.5-.2,3.5));
